const titles=['Clássicos & Cremosos','Frutas & Sorbets Veganos','Especiais & Criações'];const descriptions=['Gelatos artesanais de base cremosa.','Base de água pura e fruta fresca selecionada. 100% livre de lactose e corantes.','Criações artesanais e combinações especiais.'];
function render(){const count=`${chosen.length}/${limit()}`;widget.querySelector('#shared-flavor-counter-badge').textContent=count+' selecionados';widget.querySelector('#shared-selection-counter-text').textContent=count+' Sabores';widget.querySelector('#shared-freezer-title span:last-child').textContent=`Freezer ${active+1} — ${titles[active]}`;widget.querySelector('#shared-freezer-desc').textContent=descriptions[active];widget.querySelectorAll('.freezer-panel').forEach((p,n)=>{p.classList.toggle('hidden',n!==active);p.hidden=n!==active});widget.querySelectorAll('[data-freezer]').forEach(b=>{const selected=+b.dataset.freezer===active;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('is-active',selected)});widget.querySelectorAll('.flavor-card').forEach(card=>{const selected=chosen.some(f=>f.name===card.dataset.flavorName);card.setAttribute('aria-pressed',String(selected));card.classList.toggle('is-selected',selected);card.classList.toggle('selected',selected);card.querySelector('.check-badge').classList.toggle('hidden',!selected);const pill=card.querySelector('.status-pill');if(pill)pill.textContent=selected?'Escolhido':pill.dataset.originalLabel})}
widget.querySelectorAll('[data-freezer]').forEach(b=>b.onclick=()=>{active=+b.dataset.freezer;render()});widget.querySelectorAll('.flavor-card').forEach(card=>{card.onclick=()=>{const name=card.dataset.flavorName,index=chosen.findIndex(f=>f.name===name);if(index>=0)chosen.splice(index,1);else{if(chosen.length>=limit()){flow.toast(`Escolha até ${limit()} sabores. Desmarque um para trocar.`);return}chosen.push({name,image:card.querySelector('img').src})}render();syncSummary()};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click()}}});render();syncSummary();
function syncSummary(){if(petit&&typeof selectedGelatos!=='undefined')selectedGelatos=chosen.map(f=>f.name);if(milk)window.selectedFlavors=chosen.map(f=>f.name);if(id===8&&typeof selectedGelatos!=='undefined')selectedGelatos=chosen.map(f=>f.name);const names=chosen.map(f=>f.name).join(' + ')||'Escolha pelo menos 1 sabor';for(const key of ['summary-details','summary-flavors-line','summary-flavors']){const e=document.getElementById(key);if(e)e.textContent=names}const count=$('#bolas-selecionadas');if(count)count.textContent=chosen.length}
