window.getGelatoProduct=()=>{if(!chosen.length)return null;let price=parse($('#summary-total-price')?.textContent||$('#summary-price')?.textContent||$('#total-price')?.textContent);if(id===41)price=Number($('#preco-total')?.textContent.replace(',','.'));let details=chosen.map(f=>f.name).join(' + ');if(petit){if(typeof selectedBaseCobertura!=='undefined')details+=' · '+selectedBaseCobertura;if(typeof selectedExtras!=='undefined')details+=' · '+selectedExtras.map(e=>e.name).join(', ')}if(milk&&window.selectedCobertura)details+=' · '+window.selectedCobertura;if(id===8&&typeof selectedSauce!=='undefined')details+=' · '+selectedSauce;details+=' · '+$$('input[type=checkbox]:checked,input[type=radio]:checked').map(e=>e.closest('label')?.textContent.trim().replace(/\s+/g,' ')).filter(Boolean).join(', ');return {name:title,price:price||(banana?42:milk?32:29.9),details:details.replace(/ · $/,''),qty:1,image:$('.client-product-photo')?.src}};
